/**
 * WORLD TILEMAP - Landmass Shape Definition
 *
 * Defines which hex tiles exist in the game world (the landmass shape).
 * This is separate from region definitions - it only defines WHICH tiles to render.
 * Each tile coordinate maps to a region ID.
 *
 * This tilemap was extracted from the manually crafted landmass shape.
 * To modify the landmass, edit the tiles array below.
 */

const WorldTilemap = {
    /**
     * Get all tiles that should be rendered (the landmass)
     * This is generated by excluding unwanted tiles from a radius-7 hex grid
     * @returns {Array<{q: number, r: number}>} Array of tile coordinates
     */
    getTiles() {
        const mapRadius = 7;
        const tiles = [];

        // Columns to completely exclude
        const excludedColumns = [7];

        // Specific tiles to exclude (over water, etc.)
        const excludedTiles = [
            // Column -7
            [-7, -6], [-7, -5], [-7, -2], [-7, 0], [-7, 2], [-7, 5], [-7, 6],
            // Column -6
            [-6, -6], [-6, 1], [-6, 6],
            // Column -5
            [-5, 5],
            // Column -4
            [-4, -5], [-4, 5],
            // Column -1
            [-1, -1],
            // Column 0
            [0, -3], [0, -2], [0, -1], [0, 0],
            // Column 2
            [2, -5], [2, -2], [2, 5],
            // Column 3
            [3, -5], [3, 5],
            // Column 4
            [4, -6], [4, -1], [4, 6],
            // Column 5
            [5, -6], [5, 4], [5, 6],
            // Column 6
            [6, -6], [6, -5], [6, -4], [6, -1], [6, 0], [6, 1], [6, 4], [6, 5], [6, 6]
        ];

        // Generate all possible tiles in hexagonal grid (radius 7)
        for (let q = -mapRadius; q <= mapRadius; q++) {
            const r1 = Math.max(-mapRadius, -q - mapRadius);
            const r2 = Math.min(mapRadius, -q + mapRadius);

            for (let loop_r = r1; loop_r <= r2; loop_r++) {
                const r = -loop_r;

                // Skip excluded columns
                if (excludedColumns.includes(q)) {
                    continue;
                }

                // Skip excluded specific tiles
                if (excludedTiles.some(([eq, er]) => eq === q && er === r)) {
                    continue;
                }

                // This tile is part of the landmass
                tiles.push({ q, r });
            }
        }

        return tiles;
    },

    /**
     * Check if a tile coordinate is part of the landmass
     * @param {number} q - Axial q coordinate
     * @param {number} r - Axial r coordinate
     * @returns {boolean} True if tile should be rendered
     */
    hasTile(q, r) {
        return this.getTiles().some(tile => tile.q === q && tile.r === r);
    },

    /**
     * Get region ID for a tile coordinate
     * @param {number} q - Axial q coordinate
     * @param {number} r - Axial r coordinate
     * @returns {string} Region ID (e.g., "region_-3_-4")
     */
    getRegionId(q, r) {
        return `region_${q}_${r}`;
    },

    /**
     * Get tile count (total landmass tiles)
     * @returns {number} Number of tiles in the landmass
     */
    getTileCount() {
        return this.getTiles().length;
    }
};

console.log(`🗺️ WorldTilemap loaded: ${WorldTilemap.getTileCount()} tiles`);
